from solution import count_X


def test_issue_example_from_issue():
    """Example from issue: count of 4 in the given tuple is 0."""
    assert count_X((10, 8, 5, 2, 10, 15, 10, 8, 5, 8, 8, 2), 4) == 0  # 0 matches = 0


def test_issue_counts_three_tens():
    """Count occurrences of element 10 in a tuple with three 10s."""
    assert count_X((10, 8, 5, 2, 10, 15, 10, 8, 5, 8, 8, 2), 10) == 3  # 1+1+1 = 3


def test_issue_counts_four_eights():
    """Count occurrences of element 8 in a tuple with four 8s."""
    assert count_X((10, 8, 5, 2, 10, 15, 10, 8, 5, 8, 8, 2), 8) == 4  # 1+1+1+1 = 4


def test_issue_counts_two_fives():
    """Count occurrences of element 5 in a tuple with two 5s."""
    assert count_X((10, 8, 5, 2, 10, 15, 10, 8, 5, 8, 8, 2), 5) == 2  # 1+1 = 2


def test_issue_empty_tuple_returns_zero():
    """Count occurrences of any element in an empty tuple is 0."""
    assert count_X((), 1) == 0  # 0 matches = 0


def test_issue_singleton_match_returns_one():
    """Count occurrences when singleton tuple equals x is 1."""
    assert count_X((7,), 7) == 1  # 1 match = 1


def test_issue_singleton_mismatch_returns_zero():
    """Count occurrences when singleton tuple does not equal x is 0."""
    assert count_X((7,), 8) == 0  # 0 matches = 0


def test_issue_all_elements_equal_returns_length():
    """Count occurrences when every element equals x is the tuple length."""
    assert count_X((2, 2, 2, 2), 2) == 4  # 1+1+1+1 = 4


def test_contract_counts_value_at_both_ends():
    """Count occurrences of an element appearing at start and end."""
    assert count_X((3, 1, 2, 3), 3) == 2  # 1+1 = 2


def test_contract_counts_consecutive_duplicates():
    """Count occurrences of an element appearing consecutively."""
    assert count_X((4, 4, 4, 1), 4) == 3  # 1+1+1 = 3


def test_contract_distinguishes_similar_integers():
    """Count occurrences counts only exact matches, not similar values."""
    assert count_X((10, 1, 100, 10), 10) == 2  # 1+1 = 2
